def format_list(message, args \\ [], options \\ []) do
  case format_list(message, args, options, [], []) do
    {iolist, bound, [] = unbound} -> {:ok, iolist, bound, unbound}
    {iolist, bound, unbound} -> {:error, iolist, bound, unbound}
  end
end

def to_string(number, backend \\ default_backend(), options \\ [])
def to_string(%Decimal{coef: 0, sign: -1} = number, backend, options) do
  %{number | sign: 1} |> to_string(backend, options)
end
def to_string(number, backend, %Options{} = options) do
  case to_string(number, options.format, backend, options) do
    {:error, reason} -> {:error, reason}
    string -> {:ok, string}
  end
end

